/* Generated output/update entrypoints allow the host to schedule sample hits
 * before firmware execution and integrate afterward. The ODE5 implementation
 * is generated by Simulink; it is never reimplemented here. */
#include "plant_adapter.h"
#include <string.h>
static int useLinear;
ExtY_hover_plant_sil_T plantOutputValues;
void plantInitialize(int linear,const double *a,const double *b) {
    useLinear=linear;
    if(linear) {
        /* Build script derives this field list from the generated headers. */
        #include "plant_shared_fields.inc"
        memcpy(hover_linear_sil_P.A,a,sizeof(hover_linear_sil_P.A));
        memcpy(hover_linear_sil_P.B,b,sizeof(hover_linear_sil_P.B));
        hover_linear_sil_P.imu_nonlinear=false;
        hover_linear_sil_initialize();
    } else hover_plant_sil_initialize();
}
void plantOutputs(int controllerHit,int gyroHit,int accelHit) {
    if(useLinear) {
        hover_linear_sil_M->Timing.TaskCounters.TID[2]=controllerHit?0:1;
        hover_linear_sil_M->Timing.TaskCounters.TID[3]=gyroHit?0:1;
        hover_linear_sil_M->Timing.TaskCounters.TID[4]=accelHit?0:1;
        hover_linear_sil_output();
        memcpy(&plantOutputValues,&hover_linear_sil_Y,sizeof(plantOutputValues));
    } else {
        hover_plant_sil_M->Timing.TaskCounters.TID[2]=controllerHit?0:1;
        hover_plant_sil_M->Timing.TaskCounters.TID[3]=gyroHit?0:1;
        hover_plant_sil_M->Timing.TaskCounters.TID[4]=accelHit?0:1;
        hover_plant_sil_output(); plantOutputValues=hover_plant_sil_Y;
    }
}
void plantInputs(const double *delta) {
    if(useLinear) memcpy(hover_linear_sil_U.motor_delta,delta,4*sizeof(double));
    else memcpy(hover_plant_sil_U.motor_delta,delta,4*sizeof(double));
}
void plantAdvance(double nextTime,double step) {
    /* A shortened step lands exactly on independently configured sample
     * times. The normal default remains 1/16000 s. Solver stop time must be
     * overridden after outputs, which otherwise computes a fixed-grid stop. */
    if(useLinear) {
        hover_linear_sil_M->Timing.stepSize0=step;
        rtsiSetSolverStopTime(&hover_linear_sil_M->solverInfo,nextTime);
        hover_linear_sil_update();
    } else {
        hover_plant_sil_M->Timing.stepSize0=step;
        rtsiSetSolverStopTime(&hover_plant_sil_M->solverInfo,nextTime);
        hover_plant_sil_update();
    }
}
void plantTerminate(void) { if(useLinear) hover_linear_sil_terminate(); else hover_plant_sil_terminate(); }
